@using sv_17b449781a874886bf32c6f10b18625a.Models

<EditForm Model="Model" OnValidSubmit="HandleValidSubmit" FormName="personal-info">
    <DataAnnotationsValidator />

    <h4 class="mb-3">Personal Information</h4>

    @if (!string.IsNullOrEmpty(emailError))
    {
        <div class="alert alert-danger">@emailError</div>
    }

    <div class="row g-3">
        <div class="col-md-6">
            <label class="form-label">Full Name <span class="text-danger">*</span></label>
            <InputText class="form-control" @bind-Value="Model.FullName" placeholder="John Doe" />
            <ValidationMessage For="() => Model.FullName" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Email <span class="text-danger">*</span></label>
            <InputText class="form-control" @bind-Value="Model.Email" placeholder="john@example.com" />
            <ValidationMessage For="() => Model.Email" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Phone <span class="text-danger">*</span></label>
            <InputText class="form-control" @bind-Value="Model.Phone" placeholder="(555) 123-4567" />
            <ValidationMessage For="() => Model.Phone" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Address <span class="text-danger">*</span></label>
            <InputText class="form-control" @bind-Value="Model.Address" placeholder="123 Main St, City, State" />
            <ValidationMessage For="() => Model.Address" />
        </div>
    </div>

    <div class="d-flex justify-content-end mt-4">
        <button type="submit" class="btn btn-primary" disabled="@isValidating">
            @if (isValidating)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                <span>Validating…</span>
            }
            else
            {
                <span>Next →</span>
            }
        </button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired]
    public PersonalInfoModel Model { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback OnNext { get; set; }

    [Parameter, EditorRequired]
    public IApplicationService ApplicationService { get; set; } = default!;

    private string? emailError;
    private bool isValidating;

    private async Task HandleValidSubmit()
    {
        emailError = null;
        isValidating = true;

        try
        {
            var isEmailValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!isEmailValid)
            {
                emailError = "The email address could not be verified. Please check and try again.";
                return;
            }

            await OnNext.InvokeAsync();
        }
        finally
        {
            isValidating = false;
        }
    }
}

@using sv_17b449781a874886bf32c6f10b18625a.Models

<h4 class="mb-3">Work History</h4>

@if (validationErrors.Count > 0)
{
    <div class="alert alert-danger">
        <ul class="mb-0">
            @foreach (var error in validationErrors)
            {
                <li>@error</li>
            }
        </ul>
    </div>
}

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <WorkEntryEditor Entry="Entries[index]"
                     Index="index + 1"
                     CanRemove="Entries.Count > 1"
                     OnRemove="() => RemoveEntry(index)" />
}

<button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between mt-3">
    <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">← Back</button>
    <button type="button" class="btn btn-primary" @onclick="HandleNext">Next →</button>
</div>

@code {
    [Parameter, EditorRequired]
    public List<WorkEntryModel> Entries { get; set; } = [];

    [Parameter, EditorRequired]
    public EventCallback OnNext { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnBack { get; set; }

    private List<string> validationErrors = [];

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        validationErrors.Clear();

        for (int i = 0; i < Entries.Count; i++)
        {
            var entry = Entries[i];
            var pos = i + 1;

            if (string.IsNullOrWhiteSpace(entry.Company))
                validationErrors.Add($"Position {pos}: Company name is required.");
            if (string.IsNullOrWhiteSpace(entry.Title))
                validationErrors.Add($"Position {pos}: Job title is required.");
            if (entry.StartDate is null)
                validationErrors.Add($"Position {pos}: Start date is required.");
        }

        if (validationErrors.Count == 0)
        {
            await OnNext.InvokeAsync();
        }
    }
}

