@using sv_17b449781a874886bf32c6f10b18625a.Models

<h4 class="mb-3">Work History</h4>

@if (validationErrors.Count > 0)
{
    <div class="alert alert-danger">
        <ul class="mb-0">
            @foreach (var error in validationErrors)
            {
                <li>@error</li>
            }
        </ul>
    </div>
}

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <WorkEntryEditor Entry="Entries[index]"
                     Index="index + 1"
                     CanRemove="Entries.Count > 1"
                     OnRemove="() => RemoveEntry(index)" />
}

<button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between mt-3">
    <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">← Back</button>
    <button type="button" class="btn btn-primary" @onclick="HandleNext">Next →</button>
</div>

@code {
    [Parameter, EditorRequired]
    public List<WorkEntryModel> Entries { get; set; } = [];

    [Parameter, EditorRequired]
    public EventCallback OnNext { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnBack { get; set; }

    private List<string> validationErrors = [];

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        validationErrors.Clear();

        for (int i = 0; i < Entries.Count; i++)
        {
            var entry = Entries[i];
            var pos = i + 1;

            if (string.IsNullOrWhiteSpace(entry.Company))
                validationErrors.Add($"Position {pos}: Company name is required.");
            if (string.IsNullOrWhiteSpace(entry.Title))
                validationErrors.Add($"Position {pos}: Job title is required.");
            if (entry.StartDate is null)
                validationErrors.Add($"Position {pos}: Start date is required.");
        }

        if (validationErrors.Count == 0)
        {
            await OnNext.InvokeAsync();
        }
    }
}

